<?php
require_once __DIR__.'/execute/config.php';
require_once __DIR__.'/includes/language.php';
require_once __DIR__.'/includes/web_session.php';
require_once __DIR__.'/includes/division_schema.php';
require_once __DIR__.'/includes/division_content.php';
require_once __DIR__.'/includes/compendium_schema.php';
$pdo=new PDO("mysql:host=$dbHost;dbname=$dbName;charset=utf8mb4",$dbUser,$dbPass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
if(!validateVfnWebSession($pdo)){header('Location: index.php');exit;}
ensureDivisionManagementSchema($pdo);ensureCompendiumSchema($pdo);
$uid=(int)$_SESSION['web_user_id'];$s=$pdo->prepare('SELECT op_permission FROM users WHERE id=?');$s->execute([$uid]);$op=(int)$s->fetchColumn();
$s=$pdo->prepare("SELECT d.code,d.name FROM divisions d JOIN division_staff x ON x.division_code=d.code WHERE x.user_id=? AND x.is_active=1 AND(x.can_edit_content=1 OR x.role_code='DIR') ORDER BY d.name");$s->execute([$uid]);$divisions=$s->fetchAll(PDO::FETCH_ASSOC);
if($op>=3)$divisions=$pdo->query('SELECT code,name FROM divisions ORDER BY name')->fetchAll(PDO::FETCH_ASSOC);
$codes=array_column($divisions,'code');if($op<3&&!$codes){http_response_code(403);exit('Access denied');}
$_SESSION['web_op_permission']=$op;if(empty($_SESSION['compendium_csrf']))$_SESSION['compendium_csrf']=bin2hex(random_bytes(32));$csrf=$_SESSION['compendium_csrf'];
$cats=['general','radio','plugin','atc','training','exam','airport','rules','procedures'];$langs=vfnLanguageCodes();$id=max(0,(int)($_GET['id']??$_POST['id']??0));$message='';
function cae($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function caLoad(PDO $p,int $id){$s=$p->prepare('SELECT * FROM compendium_articles WHERE id=?');$s->execute([$id]);return $s->fetch(PDO::FETCH_ASSOC)?:null;}
function caAllowed(?array $a,int $op,array $codes):bool{return $op>=3||($a&&$a['scope_type']==='division'&&in_array($a['division_code'],$codes,true));}
$old=caLoad($pdo,$id);
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($csrf,(string)($_POST['csrf']??''))){http_response_code(403);exit('CSRF');}$action=$_POST['action']??'';
 if($action==='save'){
  $title=trim($_POST['title']??'');$slug=compendiumNormalizeTerm($_POST['slug']?:$title);$scope=($op>=3&&($_POST['scope_type']??'')==='global')?'global':'division';$div=$scope==='division'?strtoupper(trim($_POST['division_code']??'')):null;$homepage=($op>=3&&$scope==='global'&&!empty($_POST['is_homepage']))?1:0;
  $valid=(!$old||caAllowed($old,$op,$codes))&&($op>=3||in_array($div,$codes,true))&&$title!==''&&$slug!==''&&in_array($_POST['category']??'',$cats,true)&&in_array($_POST['language_code']??'',$langs,true)&&in_array($_POST['status']??'', ['draft','published','archived'],true);
  $dup=$pdo->prepare('SELECT 1 FROM compendium_articles WHERE slug=? AND id<>?');$dup->execute([$slug,$id]);
  if(!$valid)$message=t('compendium_invalid');elseif($dup->fetchColumn())$message=t('compendium_slug_exists');else{
   try{$pdo->beginTransaction();if($old){$pdo->prepare('INSERT INTO compendium_revisions(article_id,title,summary,content_html,editor_user_id)VALUES(?,?,?,?,?)')->execute([$id,$old['title'],$old['summary'],$old['content_html'],$uid]);
    $sql="UPDATE compendium_articles SET title=?,slug=?,summary=?,content_html=?,category=?,language_code=?,scope_type=?,division_code=?,airport_code=?,status=?,is_homepage=?,sort_order=?,updated_by_user_id=?,published_at=IF(?='published',COALESCE(published_at,NOW()),published_at) WHERE id=?";
    $args=[$title,$slug,trim($_POST['summary']??''),sanitizeDivisionHtml($_POST['content_html']??''),$_POST['category'],$_POST['language_code'],$scope,$div,strtoupper(trim($_POST['airport_code']??''))?:null,$_POST['status'],$homepage,(int)($_POST['sort_order']??100),$uid,$_POST['status'],$id];
   }else{$sql="INSERT INTO compendium_articles(title,slug,summary,content_html,category,language_code,scope_type,division_code,airport_code,status,is_homepage,sort_order,author_user_id,updated_by_user_id,published_at)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,IF(?='published',NOW(),NULL))";$args=[$title,$slug,trim($_POST['summary']??''),sanitizeDivisionHtml($_POST['content_html']??''),$_POST['category'],$_POST['language_code'],$scope,$div,strtoupper(trim($_POST['airport_code']??''))?:null,$_POST['status'],$homepage,(int)($_POST['sort_order']??100),$uid,$uid,$_POST['status']];}
   $pdo->prepare($sql)->execute($args);if(!$old)$id=(int)$pdo->lastInsertId();if($homepage){$pdo->prepare('UPDATE compendium_articles SET is_homepage=0 WHERE id<>?')->execute([$id]);}$pdo->prepare('DELETE FROM compendium_aliases WHERE article_id=?')->execute([$id]);$ins=$pdo->prepare('INSERT INTO compendium_aliases(article_id,alias,normalized_alias)VALUES(?,?,?)');foreach(array_unique(preg_split('/[\r\n,;]+/',$_POST['aliases']??'',-1,PREG_SPLIT_NO_EMPTY))as$a){$a=trim($a);$n=compendiumNormalizeTerm($a);if($n&&$n!==$slug)$ins->execute([$id,mb_substr($a,0,180),$n]);}$pdo->commit();header("Location: admin_compendium.php?id=$id&saved=1");exit;}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();$message=t('compendium_alias_exists');}
  }
 }elseif($action==='delete'&&$old&&caAllowed($old,$op,$codes)){foreach(['compendium_aliases','compendium_revisions']as$t)$pdo->prepare("DELETE FROM $t WHERE article_id=?")->execute([$id]);$pdo->prepare('DELETE FROM compendium_articles WHERE id=?')->execute([$id]);header('Location: admin_compendium.php?deleted=1');exit;}
 elseif($action==='restore'&&$old&&caAllowed($old,$op,$codes)){$s=$pdo->prepare('SELECT * FROM compendium_revisions WHERE id=? AND article_id=?');$s->execute([(int)$_POST['revision_id'],$id]);if($r=$s->fetch(PDO::FETCH_ASSOC)){$pdo->prepare('UPDATE compendium_articles SET title=?,summary=?,content_html=?,updated_by_user_id=? WHERE id=?')->execute([$r['title'],$r['summary'],$r['content_html'],$uid,$id]);header("Location: admin_compendium.php?id=$id&restored=1");exit;}}
}
$article=caLoad($pdo,$id);if($article&&!caAllowed($article,$op,$codes)){http_response_code(403);exit('Access denied');}
if(isset($_GET['saved']))$message=t('compendium_saved');if(isset($_GET['deleted']))$message=t('compendium_deleted');if(isset($_GET['restored']))$message=t('compendium_restored');
$aliases=[];$revisions=[];if($article){$s=$pdo->prepare('SELECT alias FROM compendium_aliases WHERE article_id=? ORDER BY alias');$s->execute([$id]);$aliases=$s->fetchAll(PDO::FETCH_COLUMN);$s=$pdo->prepare('SELECT * FROM compendium_revisions WHERE article_id=? ORDER BY created_at DESC LIMIT 25');$s->execute([$id]);$revisions=$s->fetchAll(PDO::FETCH_ASSOC);}
$where=$op>=3?'1=1':"scope_type='division' AND division_code IN(".implode(',',array_fill(0,count($codes),'?')).')';$s=$pdo->prepare("SELECT * FROM compendium_articles WHERE $where ORDER BY updated_at DESC");$s->execute($op>=3?[]:$codes);$list=$s->fetchAll(PDO::FETCH_ASSOC);
$f=$article?:['title'=>'','slug'=>'','summary'=>'','content_html'=>'<h2>'.t('compendium_new_section').'</h2><p></p>','category'=>'general','language_code'=>'en','scope_type'=>$op>=3?'global':'division','division_code'=>$codes[0]??'','airport_code'=>'','status'=>'draft','is_homepage'=>0,'sort_order'=>100];
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title><?=cae(t('compendium_manage'))?></title><style>*{box-sizing:border-box}body{margin:0;background:#07141f;color:#dcecff;font-family:Arial}.wrap{width:min(1500px,calc(100% - 30px));margin:28px auto}.layout{display:grid;grid-template-columns:320px 1fr;gap:20px}.panel{background:#0d1d2a;border:1px solid #285475;border-radius:10px;padding:18px}.list a{display:block;padding:10px;border-bottom:1px solid #274356;color:#cce8ff;text-decoration:none}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}label{color:#91b9d6;font-size:13px}input,select,textarea{width:100%;margin-top:5px;padding:10px;background:#071521;color:#fff;border:1px solid #34729b}.wide{grid-column:1/-1}.editor{min-height:420px;font-family:monospace}.btn{display:inline-block;margin:8px 4px 8px 0;padding:10px 14px;background:#176dcc;color:#fff;border:1px solid #3d8ec5;text-decoration:none;cursor:pointer}.danger{background:#8d2830}.preview{background:#fff;color:#17202a;padding:20px;min-height:120px}.msg{padding:12px;background:#173d2a}.revision{border-top:1px solid #29485d;padding:8px}@media(max-width:850px){.layout,.grid{grid-template-columns:1fr}}</style></head><body><?php require __DIR__.'/includes/header.php';?><main class="wrap"><h1><?=cae(t('compendium_admin_title'))?></h1><p><?=cae(t('compendium_admin_intro'))?></p><?php if($message):?><div class="msg"><?=cae($message)?></div><?php endif?><div class="layout"><aside class="panel"><a class="btn" href="admin_compendium.php"><?=cae(t('compendium_new_article'))?></a><a class="btn" href="compendium.php"><?=cae(t('compendium_open'))?></a><div class="list"><?php foreach($list as$x):?><a href="?id=<?=(int)$x['id']?>"><?=cae(t('compendium_status_'.$x['status']))?> · <?=cae($x['division_code']?:t('compendium_scope_global'))?><br><b><?=cae($x['title'])?></b></a><?php endforeach?></div></aside><section class="panel"><form method="post"><input type="hidden" name="csrf" value="<?=cae($csrf)?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="save"><div class="grid"><label><?=cae(t('compendium_field_title'))?><input required name="title" value="<?=cae($f['title'])?>"></label><label><?=cae(t('compendium_field_slug'))?><input name="slug" value="<?=cae($f['slug'])?>"></label><label class="wide"><?=cae(t('compendium_field_summary'))?><textarea name="summary"><?=cae($f['summary'])?></textarea></label><label><?=cae(t('compendium_field_category'))?><select name="category"><?php foreach($cats as$v):?><option value="<?=$v?>" <?=$f['category']===$v?'selected':''?>><?=cae(t('compendium_category_'.$v))?></option><?php endforeach?></select></label><label><?=cae(t('compendium_field_language'))?><select name="language_code"><?php foreach($langs as$v):?><option value="<?=$v?>" <?=$f['language_code']===$v?'selected':''?>><?=strtoupper($v)?></option><?php endforeach?></select></label><?php if($op>=3):?><label><?=cae(t('compendium_field_scope'))?><select name="scope_type"><option value="global" <?=$f['scope_type']==='global'?'selected':''?>><?=cae(t('compendium_scope_global'))?></option><option value="division" <?=$f['scope_type']==='division'?'selected':''?>><?=cae(t('compendium_scope_division'))?></option></select></label><?php endif?><label><?=cae(t('compendium_field_division'))?><select name="division_code"><option></option><?php foreach($divisions as$d):?><option value="<?=cae($d['code'])?>" <?=$f['division_code']===$d['code']?'selected':''?>><?=cae($d['name'])?></option><?php endforeach?></select></label><label><?=cae(t('compendium_field_airport'))?><input name="airport_code" value="<?=cae($f['airport_code'])?>"></label><label><?=cae(t('compendium_field_status'))?><select name="status"><?php foreach(['draft','published','archived']as$v):?><option value="<?=$v?>" <?=$f['status']===$v?'selected':''?>><?=cae(t('compendium_status_'.$v))?></option><?php endforeach?></select></label><label><?=cae(t('compendium_field_sort'))?><input type="number" name="sort_order" value="<?=(int)$f['sort_order']?>"></label><label class="wide"><?=cae(t('compendium_field_aliases'))?><textarea name="aliases" placeholder="<?=cae(t('compendium_aliases_hint'))?>"><?=cae(implode("\n",$aliases))?></textarea></label><label class="wide"><?=cae(t('compendium_field_content'))?><textarea id="source" class="editor" name="content_html"><?=cae($f['content_html'])?></textarea></label><div class="wide"><h3><?=cae(t('compendium_preview'))?></h3><div id="preview" class="preview"></div></div></div><button class="btn"><?=cae(t('save'))?></button></form><?php if($article):?><form method="post" onsubmit="return confirm('<?=cae(t('compendium_delete_confirm'))?>')"><input type="hidden" name="csrf" value="<?=cae($csrf)?>"><input type="hidden" name="id" value="<?=$id?>"><button class="btn danger" name="action" value="delete"><?=cae(t('delete'))?></button></form><h3><?=cae(t('compendium_revisions'))?></h3><?php foreach($revisions as$r):?><form method="post" class="revision"><?=cae($r['created_at'].' · '.$r['title'])?><input type="hidden" name="csrf" value="<?=cae($csrf)?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="revision_id" value="<?=(int)$r['id']?>"><button class="btn" name="action" value="restore"><?=cae(t('compendium_restore'))?></button></form><?php endforeach?><?php endif?></section></div></main><?php require __DIR__.'/includes/footer.php';?><script>const s=document.getElementById('source'),p=document.getElementById('preview');function u(){p.innerHTML=s.value}s.oninput=u;u()</script></body></html>
